from lib import *
FV="Portions de fruits et légumes"
def fv(n): return (FV,f"Portions de fruits et légumes par portion : {n}")
FZ="Instructions de congélation : "
recs=[
R(7153228,"Champignons farcis au tofu",
"Des champignons de couche farcis aux épinards et aux oignons verts, garnis de tahini et de tofu, puis rôtis.",
"2","278 g",
["2 gros champignons portobello, pieds retirés et réservés","1 cuillère à café d'huile de colza","3 oignons verts, finement hachés","150 g de tofu ferme, finement haché","100 g d'épinards surgelés, décongelés et essorés","1 bonne pincée de poivre noir","2 cuillères à café de tahini","1 cuillère à café de moutarde de Dijon","1 cuillère à soupe de basilic frais, haché","6 tomates cerises, hachées"],
["Préchauffez le four à 180 °C/thermostat 4. Placez les chapeaux de champignons (côté du dessus vers le bas) sur une plaque de cuisson légèrement huilée.","Faites chauffer l'huile dans une grande poêle à feu moyen, puis hachez finement les pieds de champignons et ajoutez-les à la poêle avec les oignons verts et le tofu.","Faites cuire 3 à 4 minutes, puis ajoutez les épinards et le poivre et faites cuire 2 à 3 minutes, en mélangeant régulièrement.","Retirez du feu et incorporez le tahini, la moutarde et le basilic.","Garnissez chaque champignon d'un dôme du mélange de tofu et faites cuire au four 15 à 20 minutes. Garnissez de tomates hachées et servez."],
["Vous pouvez utiliser des poireaux à la place des oignons verts et du persil plutôt que du basilic.","Relevez-le avec une pincée de flocons de piment ou une cuillère à café de paprika fumé.","Vous pouvez aussi farcir des moitiés de poivron à la place des champignons.",FZ+"les champignons peuvent être congelés une fois cuits. Enveloppez-les individuellement dans du papier sulfurisé et sans les tomates hachées. Décongelez 2 heures, puis réchauffez au micro-ondes ou dans un four modéré.",fv(2)]),
R(7156026,"Pavlova aux petits fruits d'été",
"Un dessert impressionnant pour toutes les occasions, plus faible en gras et en sucre, et rempli de bienfaits grâce aux petits fruits.",
"5","177 g",
["1/2 boîte de fraises fraîches (160 g)","1 petite barquette de framboises fraîches (120 g)","1 petite barquette de bleuets frais (120 g)","4 cuillères à soupe d'eau","3.5 cuillères à soupe d'édulcorant granulé","1 cuillère à café de jus de citron","6 blancs d'œufs","1 cuillère à café de crème de tartre","4 cuillères à café de fécule de maïs","200 g de yogourt grec à 0 % de matières grasses","édulcorant, au goût","quelques brins de menthe, pour servir"],
["Mettez l'eau, l'édulcorant granulé et le jus de citron dans une petite casserole à feu doux jusqu'à ce que le liquide ait réduit et commence à devenir collant.","Pendant ce temps, mettez les blancs d'œufs et la crème de tartre dans un bol et fouettez lentement ensemble jusqu'à l'obtention de pics mous.","Versez lentement le mélange d'édulcorant dans les blancs d'œufs battus.","Ajoutez délicatement la fécule de maïs et continuez à fouetter jusqu'à ce que les blancs d'œufs soient fermes.","Sur une plaque de cuisson tapissée de papier parchemin, étalez ou pochez la meringue pour former un nid d'environ 20 à 25 cm (10 pouces) de diamètre.","Faites cuire dans un four doux, à 100 °C/thermostat 1/4, environ 1 heure 20 minutes, jusqu'à ce qu'elle soit ferme et commence tout juste à colorer. Ouvrez la porte du four et laissez la meringue dans le four jusqu'à ce qu'elle soit refroidie.","Une fois refroidie, déposez délicatement la meringue sur votre assiette de service.","Mélangez le tiers des fruits avec le yogourt, en ajoutant de l'édulcorant si nécessaire. Déposez dans la meringue et garnissez du reste des petits fruits et de quelques brins de menthe."],
["Si votre meringue commence à dorer avant d'être cuite, ouvrez la porte du four quelques minutes pour réduire la chaleur.","Ne garnissez pas votre meringue avant juste avant de servir : elle deviendra détrempée si elle reste trop longtemps avec la garniture de petits fruits. Vous pouvez toutefois préparer le mélange de yogourt et de fruits à l'avance et le réfrigérer jusqu'au moment voulu.",fv(1)]),
R(7157427,"Morue sauce tomate",
"Un plat faible en gras, délicieux servi avec du riz et de la salade.",
"2","441 g",
["1 cuillère à soupe d'huile d'olive","1 gros oignon, pelé et haché","1 boîte de 400 g de tomates hachées","1 cuillère à soupe de ketchup","2 feuilles de laurier","1 cuillère à café bombée de persil séché ou 1 cuillère à soupe de persil frais haché","poivre noir fraîchement moulu","2 gros morceaux de filet de morue sans peau (environ 150 g chacun)"],
["Faites chauffer l'huile dans une poêle antiadhésive.","Ajoutez l'oignon et faites-le revenir 5 minutes, jusqu'à ce qu'il soit ramolli.","Ajoutez tous les ingrédients restants (sauf la morue), assaisonnez de poivre noir, portez à ébullition, laissez à découvert et faites mijoter doucement 15 minutes.","Déposez la morue sur la sauce, couvrez et continuez à laisser mijoter encore 15 minutes, jusqu'à ce que le poisson soit cuit. Retirez les feuilles de laurier."],
["Cette recette se prépare aussi très bien avec du saumon, du thon frais ou de l'aiglefin.","Pour relever le plat, ajoutez 2 gousses d'ail écrasées et 1 cuillère à café de paprika fumé à la sauce tomate.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(3)]),
R(7157800,"Courge butternut farcie au quinoa",
"La courge butternut devient un repas complet lorsqu'elle est garnie de quinoa, de graines et de légumes.",
"2","414 g",
["1 petite courge butternut, épépinée (500 g)","70 g de quinoa","150 ml d'eau bouillante","1 cuillère à café d'huile de colza","1 oignon, finement haché","1/2 poivron rouge, finement haché","1 cuillère à café bombée de cumin","3 gousses d'ail, écrasées","1 pincée de flocons de piment","1 cuillère à soupe de graines de citrouille","6 tomates cerises, coupées en deux","6 brins de romarin frais"],
["Préchauffez le four à 180 °C/thermostat 4. Coupez la courge en deux dans le sens de la longueur, retirez les graines et faites cuire au four 35 à 40 minutes, jusqu'à ce qu'elle soit tendre.","Pendant ce temps, mettez le quinoa dans une casserole d'eau bouillante, portez à ébullition et réduisez le feu. Couvrez et laissez mijoter doucement 10 à 15 minutes.","Mettez l'huile dans une autre casserole et faites cuire les oignons et le poivron 5 minutes. Ajoutez le cumin, l'ail et les flocons de piment et faites cuire encore 2 minutes.","Égouttez l'excédent d'eau du quinoa et incorporez-le au mélange d'oignons. Ajoutez les graines de citrouille et mélangez bien.","Déposez le quinoa en dôme sur la courge, garnissez de tomates et faites cuire au four encore 10 minutes. Servez avec des brins de romarin."],
["Vous pouvez utiliser du couscous ou du boulgour pour la farce, à la place du quinoa.","Essayez d'utiliser différentes épices, comme de la pâte de cari, ou des herbes fraîches, comme la coriandre ou l'estragon.","Garnissez d'un peu de fromage faible en gras si vous le souhaitez.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez au four ou au micro-ondes jusqu'à ce que ce soit bien chaud.",fv(4)]),
R(7160544,"Soupe verte d'été",
"Une soupe d'été rafraîchissante et magnifiquement verte, remplie de fines herbes, de légumes et de haricots flageolets.",
"4","340 g",
["2 cuillères à café d'huile de colza","1 botte de 250 g d'asperges, grossièrement hachées, tiges ligneuses retirées","2 gousses d'ail, écrasées","1 botte d'oignons verts, parés et hachés","1 boîte de 400 g de haricots flageolets, égouttés (265 g de poids égoutté)","1 cube de bouillon de légumes faible en sel dans 500 ml d'eau bouillante","1 bonne pincée de poivre blanc","1 paquet de 200 g d'épinards frais","160 g de concombre, haché","1 poignée (25 g) de fines herbes fraîches mélangées, comme le persil et le basilic","1 avocat de 150 g, pelé et dénoyauté","3 cuillères à soupe de yogourt de style grec à 0 % de matières grasses","4 tranches de concombre, hachées","3 radis, tranchés et hachés"],
["Mettez l'huile dans une casserole, ajoutez les asperges et faites cuire 3 minutes. Ajoutez l'ail et faites cuire encore 2 minutes, en mélangeant régulièrement.","Ajoutez l'oignon vert, les haricots flageolets, le bouillon et le poivre blanc et portez à ébullition. Réduisez le feu, couvrez et laissez mijoter doucement 6 à 8 minutes, jusqu'à ce que les asperges soient tendres.","Ajoutez les épinards et le concombre, ramenez à ébullition, puis retirez du feu.","Laissez refroidir complètement, puis réfrigérez. Juste avant de servir, ajoutez les herbes, l'avocat et le yogourt, puis mixez jusqu'à consistance lisse.","Versez dans des bols et garnissez de concombre et de radis hachés."],
["Essayez différentes herbes, comme la menthe ou la coriandre. C'est préférable avec une combinaison d'herbes complémentaires.","Essayez d'utiliser de la laitue ou du cresson à la place des épinards.",FZ+"peut être congelé avant d'ajouter les herbes, l'avocat et le yogourt. Décongelez au réfrigérateur, puis ajoutez les herbes, l'avocat et le yogourt et mixez.",fv(3)]),
R(7161543,"Dhansak d'agneau",
"Un cari d'épices moyennes préparé avec de l'agneau, des légumes et des lentilles dans une sauce riche et épaisse, pleine de saveur.",
"4","421 g",
["2 cuillères à café d'huile de colza","1 oignon, haché","350 g de gigot d'agneau coupé en dés","2 carottes, hachées","4 gousses d'ail, écrasées","3 cm de racine de gingembre frais, râpée","100 g de lentilles rouges","1 cube de bouillon d'agneau ou de poulet faible en sel dans 400 ml d'eau bouillante","1 boîte de 400 g de tomates hachées","1 cuillère à soupe de pâte de cari doux","1 à 2 patates douces (400 g), pelées et hachées","1 aubergine, hachée","20 g de coriandre fraîche, grossièrement hachée"],
["Mettez l'huile dans une casserole, puis ajoutez l'oignon et faites cuire 3 à 4 minutes, jusqu'à ce qu'il commence à dorer.","Ajoutez l'agneau et faites cuire encore 4 à 5 minutes, jusqu'à ce qu'il soit bien doré. Ajoutez les carottes, l'ail et le gingembre et faites cuire encore 2 à 3 minutes, en remuant régulièrement.","Ajoutez les lentilles, le bouillon, les tomates et la pâte de cari et mélangez bien. Portez à ébullition, couvrez, réduisez le feu, puis laissez mijoter 1 heure.","Ajoutez la patate douce et l'aubergine, mélangez et couvrez à nouveau. Laissez mijoter encore 20 minutes.","Vérifiez que l'agneau est tendre. Sinon, laissez mijoter encore 10 à 15 minutes. Incorporez la coriandre fraîche, en en gardant un peu pour garnir, et servez."],
["Vous pouvez préparer ce plat avec n'importe quelle viande maigre, comme le bœuf ou le porc.","Pour une version rapide, utilisez du poulet ou de la dinde en cubes et laissez mijoter 15 minutes au lieu de 1 heure, avant d'ajouter la patate douce et l'aubergine.",FZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(4)]),
R(7161660,"Choux de Bruxelles en hachis avec œuf poché",
"Un plat rassasiant, idéal pour un souper en famille ou un petit-déjeuner copieux.",
"4","362 g",
["200 g de pommes de terre","300 g de patates douces","500 g de choux de Bruxelles, parés","1 grosse pincée de poivre blanc","2 cuillères à café d'huile d'olive","1 gros oignon, finement haché","4 œufs, pochés"],
["Brossez les pommes de terre et les patates douces et retirez les imperfections, mais ne les pelez pas. Coupez-les en gros morceaux et couvrez d'eau bouillante. Laissez mijoter 10 à 12 minutes.","Ajoutez les choux de Bruxelles et remettez le couvercle. Faites cuire 7 à 10 minutes, jusqu'à ce qu'ils soient cuits, mais encore assez fermes. Égouttez tout le liquide.","Ajoutez le poivre et écrasez grossièrement pour tout mélanger, en laissant quelques morceaux de chou dans la purée. Réservez.","Mettez l'huile d'olive dans une autre grande poêle antiadhésive à feu moyen, puis ajoutez l'oignon. Faites cuire 3 à 4 minutes, en remuant régulièrement.","Ajoutez maintenant le mélange de pommes de terre et de choux dans la poêle et mélangez bien. Aplatissez-le pour qu'il couvre toute la poêle. Faites cuire 5 minutes en retournant régulièrement pour mélanger l'appareil, et répétez quelques fois pour vous assurer qu'il forme une croûte croustillante.","Déposez un œuf poché sur le dessus et servez."],
["C'est parfait pour utiliser les restes : si vous avez des pommes de terre ou des choux froids, il suffit de les réchauffer quelques minutes et de commencer à l'étape 3.","D'autres légumes, comme les carottes, le rutabaga ou les panais, conviennent aussi très bien.","Les groupes « à risque », comme les nourrissons, les enfants, les femmes enceintes, les personnes âgées et les personnes malades, devraient éviter les œufs mous, peu cuits ou crus, à moins de pouvoir garantir qu'ils sont produits selon le programme d'assurance qualité Lion code.",fv(2)]),
R(7163244,"Tasse au micro-ondes : quiche sans croûte au maïs et au cheddar",
"Une collation savoureuse, pleine de bonté, mais faible en sel, idéale pour un souper instantané ou un goûter rapide pour les enfants.",
"1","172 g",
["1 œuf, battu","2 cuillères à soupe de yogourt de style grec à 0 % de matières grasses","1 cuillère à café bombée de fécule de maïs","15 g de cheddar à teneur réduite en gras, finement râpé","2 oignons verts, finement hachés","40 g de maïs surgelé, décongelé","1 bon tour de moulin de poivre noir","1/2 cuillère à café d'huile de colza"],
["Mettez l'œuf dans un bol et incorporez en battant le yogourt, la fécule de maïs et le fromage. Incorporez l'oignon vert et le maïs. Ajoutez un tour de moulin de poivre.","Huilez légèrement une tasse et ajoutez les ingrédients. Faites chauffer deux minutes à puissance maximale (800 W). Laissez reposer 1 minute avant de servir."],
["Peut se manger directement dans la tasse ou être démoulé dans une assiette et servi avec de la salade ou des légumes de saison.","Les petits pois surgelés conviennent bien à la place du maïs, ou essayez un mélange des deux.","Ajoutez du basilic, de la ciboulette, de la coriandre ou du persil frais pour plus de saveur.",fv(0)]),
R(7165971,"Bouillabaisse",
"Une soupe méditerranéenne copieuse aux fruits de mer, remplie de légumes et d'ail. Un repas rassasiant dans un bol.",
"4","500 g",
["1 patate douce, pelée et coupée en cubes (200 g)","1 carotte, coupée en petits dés (100 g)","1 cube de bouillon de poisson, dissous dans 600 ml d'eau","1/2 bulbe de fenouil, tranché (175 g)","1 poivron jaune, tranché (140 g)","1 poireau, haché (150 g)","1 toute petite pincée de curcuma (pour la couleur, moins cher que le safran traditionnel)","1 bonne pincée de poivre blanc","2 gousses d'ail, écrasées","2 cuillères à café d'huile de tournesol","4 filets de daurade (90 g chacun), coupés en deux pour obtenir 8 morceaux","1 paquet de 150 g de crevettes royales cuites et décortiquées","1 paquet de 150 g de chair de moules cuite et réfrigérée","2 grosses tomates, pelées, épépinées et coupées en petits morceaux (100 g de chair)","1 cuillère à soupe de persil finement haché","1 bon tour de moulin de poivre noir"],
["Mettez la patate douce et la carotte dans une casserole avec le bouillon, portez à ébullition, puis réduisez le feu, couvrez et laissez mijoter 7 minutes.","Ajoutez le fenouil, le poivron jaune, le poireau, le curcuma, le poivre blanc et l'ail, mélangez, puis couvrez et laissez mijoter encore 5 minutes.","Pendant ce temps, mettez 1 cuillère à café d'huile dans une grande poêle antiadhésive à feu moyen-vif. Lorsque la poêle est chaude, ajoutez 4 morceaux de poisson, côté peau vers le bas, et faites cuire 2 à 3 minutes. Retournez-les et faites cuire encore 1 à 2 minutes. Placez sur une assiette chaude et faites cuire les autres filets de poisson avec une autre cuillère à café d'huile : si vous avez une poêle assez grande, vous pouvez le faire en une seule fois.","Ajoutez les moules et les crevettes aux légumes et au bouillon, portez à ébullition et faites cuire 2 minutes.","Répartissez les légumes, les crevettes, les moules et le bouillon entre 4 bols. Déposez les filets de poisson sur le dessus, saupoudrez de persil, de chair de tomate hachée et d'un peu de poivre noir, et servez."],
["La bouillabaisse était traditionnellement préparée avec des restes de poisson, selon ce qui était de saison : pratiquement n'importe quel poisson convient donc.","Pour peler les tomates, plongez-les dans l'eau bouillante 1 minute et la peau se retire facilement.",fv(2)]),
R(7176015,"Soupe au chou frisé et aux lentilles vertes",
"Une soupe nutritive, rapide à préparer et super saine.",
"4","362 g",
["2 cuillères à café d'huile de tournesol","2 oignons, finement hachés","1 grosse carotte, coupée en dés","1 branche de céleri, hachée","1 à 2 gousses d'ail, écrasées","1 cuillère à café de cumin moulu","1 cuillère à soupe de concentré de tomate","1 boîte de 400 g de lentilles vertes dans l'eau (ajoutez aussi l'eau)","200 g de cavolo nero (chou kale noir) ou de chou frisé, haché (grosses tiges retirées)","500 ml de bouillon de légumes","poivre noir, au goût"],
["Mettez l'huile dans une casserole à feu moyen, ajoutez les oignons et remuez 7 à 10 minutes, jusqu'à ce qu'ils soient bien dorés.","Ajoutez la carotte et le céleri et faites cuire encore 2 à 3 minutes en remuant régulièrement.","Ajoutez maintenant l'ail, le cumin, le concentré de tomate et les lentilles, et mélangez bien.","Ajoutez le bouillon, portez à ébullition, réduisez le feu, couvrez et laissez mijoter doucement 12 minutes.","Ajoutez le chou frisé, remettez le couvercle et laissez mijoter encore 5 minutes, assaisonnez de poivre et servez."],
["Vous pouvez utiliser n'importe quel bouillon, comme du poulet ou du bœuf. Les bouillons peuvent être riches en sel : choisissez donc des options réduites en sel chaque fois que possible.","Essayez d'ajouter une poitrine de poulet effilochée ou des morceaux de tofu mariné ou fumé.","Vous pouvez aussi ajouter d'autres légumes, comme des poivrons, des courgettes, du brocoli ou du maïs en conserve.",FZ+"congelez en portions, puis décongelez au réfrigérateur, ou au micro-ondes, en prenant soin de remuer régulièrement.",fv(3)]),
R(7176104,"Fouet de rhubarbe",
"Un dessert de rhubarbe compotée, sucrée avec un édulcorant artificiel et incorporée à du yogourt faible en gras et de la crème fraîche.",
"6","117 g",
["400 g de rhubarbe, coupée en morceaux de 1 cm","édulcorant artificiel, au goût (équivalent à 8 cuillères à café de sucre, p. ex. 8 comprimés de stévia, écrasés)","150 g de yogourt grec à 0 % de matières grasses","100 g de crème fraîche à teneur réduite en gras"],
["Mettez la rhubarbe dans une casserole avec 3 cuillères à soupe d'eau. Portez à ébullition, réduisez le feu, couvrez et laissez mijoter 6 minutes, en remuant régulièrement et en ajoutant une autre cuillère à soupe d'eau si ça commence à attacher. La rhubarbe doit être tendre, mais garder sa forme.","Transférez la rhubarbe dans un bol et ajoutez l'édulcorant artificiel, le cas échéant. Mélangez bien et goûtez en ajoutant un peu plus d'édulcorant artificiel si nécessaire, puis laissez refroidir. N'oubliez pas que les fruits contiennent des sucres naturels : ne sucrez donc pas trop.","Dans un bol, mélangez le yogourt et la crème fraîche et incorporez la rhubarbe. Répartissez dans des verres et réfrigérez avant de servir."],
["Peut être préparé à l'avance et conservé au réfrigérateur quelques heures. Ou, si vous voulez le préparer la veille du service, réfrigérez simplement la rhubarbe à part et mélangez-la avec le yogourt et la crème fraîche au moment voulu.","Cette recette se prépare bien avec d'autres fruits acidulés, comme les groseilles à maquereau ou les groseilles rouges.","Vous pouvez utiliser la plupart des fruits, mais vous n'aurez pas besoin de sucrer autant si le fruit est sucré. Essayez les abricots, les pêches, les nectarines, les framboises ou les cerises.","Cette recette utilise du yogourt à 0 % de matières grasses et de la crème fraîche à teneur réduite en gras, mais vous pouvez utiliser une version nature de votre choix. Toutefois, cela modifiera les valeurs nutritionnelles et la texture du plat.","Pour une version végétalienne, utilisez du yogourt de soja ou de noix de coco non sucré."]),
R(7177299,"Soupe toscane aux haricots",
"Cette soupe consistante fait un repas rassasiant et nutritif, et s'adapte facilement pour inclure vos légumes préférés.",
"4","396 g",
["1 cuillère à café d'huile d'olive","1 oignon, haché","1 poivron jaune, haché","1 carotte, coupée en dés","500 ml de bouillon de légumes sans gluten et faible en sel","1 boîte de 400 g de tomates hachées","2 feuilles de chou, hachées","1 cuillère à café bombée d'origan","1/2 cuillère à café de thym","1 boîte de 400 g de haricots borlotti, égouttés","2 à 4 gousses d'ail, écrasées","2 cuillères à café de pesto","poivre noir, un copeau de fromage et des brins de basilic frais, pour servir"],
["Mettez l'huile dans une casserole et incorporez l'oignon, le poivron et la carotte. Remuez régulièrement 5 minutes, jusqu'à ce qu'ils commencent à dorer.","Ajoutez le bouillon, les tomates, le chou, l'origan, le thym, les haricots et l'ail. Portez à ébullition, puis réduisez le feu, couvrez et laissez mijoter 10 minutes.","Versez dans des bols, ajoutez une noix de pesto dans chacun et saupoudrez de beaucoup de poivre noir. Pour servir, ajoutez un copeau de fromage, si vous le souhaitez, et un brin de basilic frais, pour garnir."],
["Comme beaucoup de recettes traditionnelles, cette soupe se prépare généralement avec ce qui est disponible. Vous pouvez ajouter toutes sortes de légumes, comme de la citrouille, des courgettes ou du céleri, ou ajouter différents haricots, des pâtes, ou même de la viande, comme du jambon.","Les haricots borlotti sont faibles en gras, riches en fibres alimentaires et constituent une bonne source de protéines et de folate.","L'utilisation d'un fromage au goût prononcé, comme le parmesan, le grana padano ou le cheddar, permet d'en utiliser moins dans votre cuisine tout en profitant d'un excellent goût.",FZ+"congelez en portions, puis décongelez au réfrigérateur, ou au micro-ondes en remuant régulièrement.",fv(3)]),
R(7178593,"Poires pochées roses",
"Des poires pochées dans un sirop sans sucre parfumé à l'anis étoilé et à la cannelle.",
"4","312 g",
["4 poires fermes, légèrement pas tout à fait mûres, pelées avec la queue laissée intacte","150 ml de sirop de cassis sans sucre","500 à 600 ml d'eau bouillante (assez pour couvrir les poires)","2 anis étoilés","1 bâton de cannelle"],
["Pelez les poires et retirez le cœur par la base à l'aide d'un petit couteau ou d'un éplucheur. Coupez la base à plat pour que les poires tiennent debout.","Mettez les poires dans une casserole avec le sirop dilué 3:1, en veillant à ce qu'elles soient complètement immergées.","Ajoutez l'anis étoilé et le bâton de cannelle, puis portez à ébullition. Réduisez le feu et laissez mijoter 20 à 30 minutes, jusqu'à ce que les poires soient tendres.","Retirez de la casserole et réservez. Faites bouillir le liquide 10 à 15 minutes, jusqu'à ce qu'il soit réduit à environ 200 ml, puis retirez l'anis étoilé et le bâton de cannelle.","Placez les poires sur un plat de service et arrosez de sauce. Servez avec une cuillerée de yogourt faible en gras ou d'une alternative sans produits laitiers."],
["Se prépare très bien avec des pommes à la place des poires.","Essayez un autre sirop ou ajoutez quelques tranches de gingembre frais ou 2 clous de girofle.",fv(1)]),
R(7179097,"Pasanda aux champignons",
"Ce délicieux cari végétarien réunit une variété d'épices pour créer une sauce savoureuse qui se marie parfaitement avec les champignons châtaigne. Cette recette a été sélectionnée en partenariat avec Slimming World.",
"4","646 g",
["enduit de cuisson en aérosol faible en calories","1 oignon, finement tranché","4 gousses d'ail, écrasées","1 morceau de 3 cm de racine de gingembre frais, pelé et râpé","1 piment vert, finement haché, épépiné si vous le souhaitez","2 cuillères à café de graines de cumin","1 cuillère à café de graines de coriandre","1/2 cuillère à café de fenugrec moulu","1/2 cuillère à café de curcuma moulu","1 cuillère à café de garam masala séché","1/2 cuillère à café de piment doux en poudre (facultatif)","400 g de tomates en conserve","400 ml de boisson aux amandes nature non sucrée","1 kg de champignons châtaigne, coupés en deux s'ils sont gros","1 pincée de filaments de safran, trempés dans 1 cuillère à soupe d'eau bouillante","1 feuille de laurier séchée","1 bâton de cannelle","4 cuillères à soupe de yogourt nature sans gras et non sucré, pour servir","20 g de feuilles de coriandre fraîche, pour servir",("Pour le riz pilaf","200 g de riz basmati sec"),("Pour le riz pilaf","1 bâton de cannelle"),("Pour le riz pilaf","4 gousses de cardamome verte, écrasées"),("Pour le riz pilaf","3 clous de girofle"),("Pour le riz pilaf","1 pincée de filaments de safran")],
["Vaporisez une grande poêle profonde antiadhésive de quelques pressions d'enduit de cuisson faible en calories et placez-la à feu moyen. Faites revenir l'oignon 5 minutes, jusqu'à ce qu'il soit ramolli. Ajoutez l'ail, le gingembre et le piment vert avec un filet d'eau, puis faites revenir 3 minutes. Ajoutez les épices et un peu d'eau et faites revenir 2 minutes.","Ajoutez les tomates et la boisson aux amandes dans la poêle, et portez le tout à frémissement. Laissez mijoter doucement 8 à 10 minutes, ou jusqu'à ce que les tomates se défassent, en remuant fréquemment.","Mettez 200 g de riz basmati sec dans une casserole antiadhésive avec couvercle avec 1 bâton de cannelle, les gousses de cardamome, les clous de girofle et le safran. Versez assez d'eau pour dépasser le riz de la hauteur d'un ongle et placez à feu moyen-vif. Portez à frémissement, laissez bouillonner 1 minute et couvrez. Réduisez le feu au minimum et, sans retirer le couvercle, faites cuire 20 minutes, ou jusqu'à ce que tout le liquide soit absorbé.","Transférez le mélange de tomates dans un grand pichet gradué, puis mixez en une sauce lisse à l'aide d'un mélangeur à main. Transférer la sauce dans un pichet plutôt que de la garder dans la casserole aide le mélangeur à la mixer plus finement. (Vous pouvez aussi utiliser un mélangeur sur pied.) Réservez.","Vaporisez une grande poêle antiadhésive de quelques pressions d'enduit de cuisson faible en calories et placez-la à feu moyen-vif. Lorsqu'elle est chaude, ajoutez la moitié des champignons et faites-les revenir 5 à 6 minutes, en remuant de temps en temps, jusqu'à ce qu'ils deviennent d'un brun doré profond. Transférez dans une assiette et répétez avec le reste des champignons.","Remettez la sauce dans la poêle. Ajoutez le safran, la feuille de laurier et la cannelle, et portez à frémissement. Ajoutez les champignons et laissez mijoter 8 à 10 minutes, en remuant fréquemment. Assaisonnez de poivre. Répartissez entre 4 bols, en retirant la feuille de laurier et la cannelle. Garnissez de yogourt et de coriandre.","Égrenez le riz à la fourchette pour un résultat parfait, en retirant la cannelle, les gousses de cardamome et les clous de girofle pour servir."],
["Utilisez du riz basmati brun pour augmenter les fibres.","Vérifiez que les mélanges d'épices ou d'assaisonnements ne contiennent pas d'ingrédients ajoutés, comme du sucre, du sel, de la farine ou de l'huile. Choisissez si possible des mélanges composés uniquement d'herbes et d'épices.","Vous pouvez utiliser le yogourt nature de votre choix. Toutefois, cela modifiera les valeurs nutritionnelles et la texture du plat.",fv(4)]),
R(7181351,"Chou-fleur cuit au four avec haricots noirs et noix de coco",
"Comptant pour 2 de vos 5 portions de fruits et légumes par jour, ces savoureux choux-fleurs rôtis sont à la fois adaptés aux végétaliens et délicieux.",
"4","330 g",
["le jus de 2 limes","1 gros chou-fleur, coupé en 6 quartiers de taille égale","2 cuillères à café d'huile de colza","1 cuillère à soupe de graines de moutarde noire","1 morceau de 2 pouces de racine de gingembre frais, pelé et finement haché","2 grosses gousses d'ail, finement hachées","1 gros piment vert, épépiné et finement haché","1 poivron rouge, évidé, épépiné et grossièrement haché","2 cuillères à café de curcuma","400 ml de lait de coco léger","400 g de haricots noirs en conserve, égouttés et rincés","1 petite poignée de coriandre fraîche, grossièrement hachée"],
["Préchauffez le four à 200 °C/180 °C chaleur tournante/thermostat 6. Portez une grande casserole d'eau à ébullition. Ajoutez le jus de 1 lime. Blanchissez le chou-fleur 4 minutes. Égouttez bien et réservez.","Placez un grand plat à rôtir résistant à la chaleur à feu doux. Ajoutez l'huile de colza et faites chauffer doucement. Ajoutez les graines de moutarde noire et faites-les grésiller 40 à 50 secondes, jusqu'à ce qu'elles éclatent. Ajoutez le gingembre, l'ail, le piment, le poivron rouge et le curcuma et faites cuire en remuant constamment 2 minutes. Versez le lait de coco et portez à ébullition. Disposez le chou-fleur dans le plat à rôtir et arrosez-le d'une partie de la sauce. Faites rôtir 20 minutes. Arrosez à nouveau de sauce et parsemez les haricots noirs dans la sauce en mélangeant bien. Remettez au four 5 minutes.","Pressez le reste du jus de lime et parsemez de coriandre avant de servir."],
[fv(2)]),
]
save(6,recs)
